.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 matmul_kernel_param_0,
    .param .u64 matmul_kernel_param_1,
    .param .u64 matmul_kernel_param_2,
    .param .u32 matmul_kernel_param_3,
    .param .u32 matmul_kernel_param_4,
    .param .u32 matmul_kernel_param_5,
    .param .u32 matmul_kernel_param_6
)
{
    .reg .pred %pA, %pB, %pC, %pK2;
    .reg .b32 %tx, %ty, %bx, %by, %bz, %row, %col, %kk, %kend;
    .reg .b32 %M, %N, %K, %CHUNK;
    .reg .b32 %acol, %brow, %idx, %off;
    .reg .b64 %gA, %gB, %gC, %addr, %rdT1;
    .reg .b64 %rdAsub, %rdBsub, %rdSA, %rdSB, %rdArow, %rdBcol;
    .reg .f32 %acc, %fa, %fb;
    .shared .align 4 .f32 Asub[272];
    .shared .align 4 .f32 Bsub[272];
    ld.param.u64 %gA, [matmul_kernel_param_0];
    ld.param.u64 %gB, [matmul_kernel_param_1];
    ld.param.u64 %gC, [matmul_kernel_param_2];
    ld.param.u32 %M,  [matmul_kernel_param_3];
    ld.param.u32 %N,  [matmul_kernel_param_4];
    ld.param.u32 %K,  [matmul_kernel_param_5];
    ld.param.u32 %CHUNK, [matmul_kernel_param_6];
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;
    mov.u32 %bz, %ctaid.z;
    // Global row/col handled by this thread.
    shl.b32 %row, %by, 4;
    add.u32 %row, %row, %ty;
    shl.b32 %col, %bx, 4;
    add.u32 %col, %col, %tx;
    mov.u64 %rdAsub, Asub;
    mov.u64 %rdBsub, Bsub;
    // rdSA = &Asub[ty*17 + tx], rdSB = &Bsub[ty*17 + tx]
    mul.lo.u32 %off, %ty, 17;
    add.u32 %off, %off, %tx;
    shl.b32 %off, %off, 2;
    cvt.u64.u32 %rdT1, %off;
    add.u64 %rdSA, %rdAsub, %rdT1;
    add.u64 %rdSB, %rdBsub, %rdT1;
    // rdArow = &Asub[ty*17], rdBcol = &Bsub[tx]
    mul.lo.u32 %off, %ty, 68;
    cvt.u64.u32 %rdT1, %off;
    add.u64 %rdArow, %rdAsub, %rdT1;
    shl.b32 %off, %tx, 2;
    cvt.u64.u32 %rdT1, %off;
    add.u64 %rdBcol, %rdBsub, %rdT1;
