    // Load A[row, kk+tx] with bounds check.
    add.u32 %acol, %kk, %tx;
    setp.lt.u32 %pA, %row, %M;
    setp.lt.u32 %pB, %acol, %K;
    and.pred %pC, %pA, %pB;
    mov.f32 %fa, 0f00000000;
    @!%pC bra SKIP_A;
    mul.lo.u32 %idx, %row, %K;
    add.u32 %idx, %idx, %acol;
    mul.wide.u32 %addr, %idx, 4;
    add.u64 %addr, %addr, %gA;
    ld.global.f32 %fa, [%addr];
