    add.u32 %brow, %kk, %ty;
    setp.lt.u32 %pA, %brow, %K;
    setp.lt.u32 %pB, %col, %N;
    and.pred %pC, %pA, %pB;
    mov.f32 %fb, 0f00000000;
    @!%pC bra SKIP_B;
    mul.lo.u32 %idx, %brow, %N;
    add.u32 %idx, %idx, %col;
    mul.wide.u32 %addr, %idx, 4;
    add.u64 %addr, %addr, %gB;
