    ld.shared.f32 %fa, [%rdArow+4];
    ld.shared.f32 %fb, [%rdBcol+68];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+8];
