    ld.shared.f32 %fa, [%rdArow+12];
    ld.shared.f32 %fb, [%rdBcol+204];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+16];
    ld.shared.f32 %fb, [%rdBcol+272];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+20];
    ld.shared.f32 %fb, [%rdBcol+340];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+24];
    ld.shared.f32 %fb, [%rdBcol+408];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+28];
    ld.shared.f32 %fb, [%rdBcol+476];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+32];
    ld.shared.f32 %fb, [%rdBcol+544];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+36];
    ld.shared.f32 %fb, [%rdBcol+612];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+40];
    ld.shared.f32 %fb, [%rdBcol+680];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+44];
    ld.shared.f32 %fb, [%rdBcol+748];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+48];
    ld.shared.f32 %fb, [%rdBcol+816];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+52];
    ld.shared.f32 %fb, [%rdBcol+884];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+56];
    ld.shared.f32 %fb, [%rdBcol+952];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    ld.shared.f32 %fa, [%rdArow+60];
    ld.shared.f32 %fb, [%rdBcol+1020];
    fma.rn.f32 %acc, %fa, %fb, %acc;
    bar.sync 0;
    add.u32 %kk, %kk, 16;
    setp.lt.u32 %pK2, %kk, %kend;
    @%pK2 bra LOOP_K;
STORE:
    // Atomically accumulate partial C[row, col] with bounds check.
    setp.lt.u32 %pA, %row, %M;
    setp.lt.u32 %pB, %col, %N;
    and.pred %pC, %pA, %pB;
    @!%pC bra DONE;
    mul.lo.u32 %idx, %row, %N;
    add.u32 %idx, %idx, %col;
    mul.wide.u32 %addr, %idx, 4;
    add.u64 %addr, %addr, %gC;
    red.global.add.f32 [%addr], %acc;
