            grid=((N + 15) // 16, (M + 15) // 16, SPLIT_K),
            block=(16, 16, 1),
            arguments=[A, B, C, u32(M), u32(N), u32(K), u32(chunk)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
